package tr.kasaba.test;
import com.google.gson.Gson;
import java.util.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.block.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
/** Local test adapter. Never included in the production distribution. */
public final class VampirProbe extends JavaPlugin {
 private JavaPlugin game;private final Gson json=new Gson();
 @Override public void onEnable(){if(!getServer().getIp().equals("127.0.0.1"))throw new IllegalStateException("Loopback required");game=(JavaPlugin)Bukkit.getPluginManager().getPlugin("KasabaVampirKoylu");Bukkit.getMessenger().registerIncomingPluginChannel(this,"kasaba_test:vampir",(ch,p,data)->{String op=new String(data,StandardCharsets.UTF_8);try{String[] a=op.split("\\|",-1);if(data.length>2048)throw new IllegalArgumentException();switch(a[0]){
 case "CMD"->{if(!Set.of("vk","v","lobi","oyunlar").contains(a[1].split(" ")[0]))throw new IllegalArgumentException();PlayerCommandPreprocessEvent event=new PlayerCommandPreprocessEvent(p,"/"+a[1]);Bukkit.getPluginManager().callEvent(event);if(!event.isCancelled())Bukkit.dispatchCommand(p,a[1]);}
 case "ADMIN"->p.setOp(true);
 case "USER"->p.setOp(false);
 case "STATE"->state(p);
 case "SEED"->{p.closeDialog();p.closeInventory();p.getInventory().clear();p.getInventory().setItem(0,new ItemStack(Material.DIAMOND,7));p.setItemOnCursor(new ItemStack(Material.EMERALD,3));p.setGameMode(GameMode.SURVIVAL);p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SPEED,12000,0));p.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.ABSORPTION,12000,0));p.setAbsorptionAmount(4);p.setLevel(11);p.setExp(.4f);}
 case "POSE"->call(game,"teleportInternal",p,new Location(p.getWorld(),Double.parseDouble(a[1]),Double.parseDouble(a[2]),Double.parseDouble(a[3])));
 case "STATION"->{Object r=room(p);int i=Integer.parseInt(a[1]);Class<?> c=Class.forName("tr.kasabatr.vampir.MapLayout",true,game.getClass().getClassLoader());Field f=c.getDeclaredField("STATIONS");f.setAccessible(true);Object s=((List<?>)f.get(null)).get(i);Location l=(Location)call(s,"location",p.getWorld());call(game,"teleportInternal",p,l.clone().add(1,0,0));p.getInventory().setHeldItemSlot(2);PlayerInteractEvent e=new PlayerInteractEvent(p,Action.RIGHT_CLICK_BLOCK,null,l.getBlock(),org.bukkit.block.BlockFace.UP,EquipmentSlot.HAND);Bukkit.getPluginManager().callEvent(e);}
 case "COMPASS"->{ItemStack compass=Arrays.stream(p.getInventory().getContents()).filter(Objects::nonNull).filter(i->i.getType()==Material.COMPASS).findFirst().orElseThrow();PlayerInteractEvent e=new PlayerInteractEvent(p,Action.RIGHT_CLICK_AIR,compass,null,org.bukkit.block.BlockFace.UP,EquipmentSlot.HAND);Bukkit.getPluginManager().callEvent(e);}
 case "BELL"->{Object r=room(p);call(game,"teleportInternal",p,new Location(p.getWorld(),1.5,69,.5));PlayerInteractEvent e=new PlayerInteractEvent(p,Action.RIGHT_CLICK_BLOCK,null,p.getWorld().getBlockAt(0,70,0),org.bukkit.block.BlockFace.UP,EquipmentSlot.HAND);Bukkit.getPluginManager().callEvent(e);}
 case "EXPIRE"->{Object r=room(p);set(r,field(r,"phase").toString().equals("DAY")?"dayRemaining":"seconds",1);call(r,"tick");}
 case "HIT"->{Player q=Bukkit.getPlayerExact(a[1]);q.setNoDamageTicks(0);q.damage(1,p);}
 case "ARROW"->{Player q=Bukkit.getPlayerExact(a[1]);Arrow arrow=p.launchProjectile(Arrow.class);q.setNoDamageTicks(0);q.damage(1,org.bukkit.damage.DamageSource.builder(org.bukkit.damage.DamageType.ARROW).withCausingEntity(p).withDirectEntity(arrow).build());arrow.remove();}
 case "MISS"->{Arrow arrow=p.launchProjectile(Arrow.class);arrow.remove();}
 case "GUARDS"->{BlockBreakEvent b=new BlockBreakEvent(p.getLocation().clone().add(0,-1,0).getBlock(),p);BlockPlaceEvent place=new BlockPlaceEvent(p.getLocation().getBlock(),p.getLocation().getBlock().getState(),p.getLocation().clone().add(0,-1,0).getBlock(),new ItemStack(Material.STONE),p,true,EquipmentSlot.HAND);EntityDamageEvent hurt=new EntityDamageEvent(p,EntityDamageEvent.DamageCause.FALL,1);FoodLevelChangeEvent hunger=new FoodLevelChangeEvent(p,10);for(var e:List.of(b,place,hurt,hunger))Bukkit.getPluginManager().callEvent(e);say(p,"guards:"+json.toJson(Map.of("break",b.isCancelled(),"place",place.isCancelled(),"damage",hurt.isCancelled(),"hunger",hunger.isCancelled())));}
 case "MAP"->{int unsafe=0;Class<?> c=Class.forName("tr.kasabatr.vampir.MapLayout",true,game.getClass().getClassLoader());Method seat=c.getDeclaredMethod("seat",World.class,int.class);seat.setAccessible(true);for(int i=0;i<20;i++){Location l=(Location)seat.invoke(null,p.getWorld(),i);if(!l.getBlock().isPassable()||!l.clone().add(0,1,0).getBlock().isPassable()||!l.clone().add(0,-1,0).getBlock().getType().isSolid())unsafe++;}say(p,"map:"+json.toJson(Map.of("unsafeSeats",unsafe,"locator",p.getWorld().getGameRuleValue(GameRule.LOCATOR_BAR),"border",p.getWorld().getWorldBorder().getSize())));}
 case "RECOVERY"->{if(room(p)!=null)throw new IllegalArgumentException();Class<?> c=Class.forName("tr.kasabatr.vampir.PlayerBackup",true,game.getClass().getClassLoader());Method m=c.getDeclaredMethod("save",java.io.File.class,Player.class);m.setAccessible(true);m.invoke(null,game.getDataFolder(),p);p.getInventory().clear();p.setItemOnCursor(null);}
 default->throw new IllegalArgumentException("Unknown operation");}say(p,"done:"+op);}catch(Throwable e){getLogger().log(java.util.logging.Level.SEVERE,"Probe failed",e);say(p,"error:"+e);}});}
 private Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 private void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 private Object call(Object o,String name,Object... args)throws Exception{Method m=Arrays.stream(o.getClass().getDeclaredMethods()).filter(x->x.getName().equals(name)&&x.getParameterCount()==args.length).findFirst().orElseThrow();m.setAccessible(true);return m.invoke(o,args);}
 private Object room(Player p)throws Exception{return ((Map<?,?>)field(game,"membership")).get(p.getUniqueId());}
 private void state(Player p)throws Exception{Map<String,Object>d=new LinkedHashMap<>();d.put("uuid",p.getUniqueId().toString());d.put("world",p.getWorld().getName());d.put("mode",p.getGameMode().name());d.put("x",p.getX());d.put("y",p.getY());d.put("z",p.getZ());d.put("items",Arrays.stream(p.getInventory().getContents()).filter(Objects::nonNull).map(i->i.getType()+":"+i.getAmount()).toList());d.put("cursor",p.getItemOnCursor().getType()+":"+p.getItemOnCursor().getAmount());d.put("absorption",p.getAbsorptionAmount());d.put("level",p.getLevel());d.put("effects",p.getActivePotionEffects().stream().map(e->e.getType().getKey().getKey()).toList());d.put("backup",new java.io.File(game.getDataFolder(),"recoveries/"+p.getUniqueId()+".yml").isFile());d.put("active",((Set<?>)field(game,"lobby")).contains(p.getUniqueId()));d.put("roomCount",((Map<?,?>)field(game,"rooms")).size());Object r=room(p);if(r!=null){d.put("room",field(r,"id"));d.put("phase",field(r,"phase").toString());d.put("demo",field(r,"demo"));d.put("members",((Set<?>)field(r,"members")).size());d.put("alive",((Set<?>)field(r,"alive")).contains(p.getUniqueId()));d.put("aliveCount",((Set<?>)field(r,"alive")).size());d.put("role",String.valueOf(((Map<?,?>)field(r,"roles")).get(p.getUniqueId())));d.put("shots",((Map<?,?>)field(r,"hunterShots")).get(p.getUniqueId()));d.put("taskDone",field(r,"taskDone"));List<Map<String,Object>> tasks=new ArrayList<>();for(Object t:((Map<?,?>)field(r,"tasks")).getOrDefault(p.getUniqueId(),null)==null?List.of():(List<?>)((Map<?,?>)field(r,"tasks")).get(p.getUniqueId()))tasks.add(Map.of("station",field(t,"station"),"kind",field(t,"kind"),"step",field(t,"step"),"completed",field(t,"completed"),"carrying",field(t,"carrying")));d.put("tasks",tasks);d.put("speaker",call(r,"isSpeaker",p.getUniqueId()));}say(p,"state:"+json.toJson(d));}
 private void say(Player p,String text){p.sendMessage(net.kyori.adventure.text.Component.text("vampir-probe:"+text));}
}
